"""Credentials generated by oasis (v0.16.0 S2): one 0600 env file is the database account of the
compose service and of Odoo; odoo.conf stays password-free; nothing prints a password.

Synthetic fixtures only: the setup fixture of test_setup (fake uv, scratch git and machine file), the
lifecycle fixture of test_lifecycle (fake docker and environment Python) and a fake psycopg2 module
for the connection probe. No real database, container or Odoo runs.
"""
import oasis_test_env  # noqa: F401  first: XDG_CONFIG_HOME is scratch (tests/oasis_test_env.py)
import fcntl
import hashlib
import importlib.util
import json
import os
from pathlib import Path
import pty
import re
import shlex
import shutil
import subprocess
import sys
import tempfile
import unittest

import test_lifecycle as lifecycle
import test_setup

ROOT = lifecycle.STAGE
ACCOUNT = ROOT / 'tools' / 'db_account.py'
MARKER = 'credentials-must-not-print-this'
# A fake psycopg2: connect() records its keyword arguments in FAKE_PG_LOG, then fails with
# FAKE_PG_ERROR when it is set; FAKE_PG_MISSING makes the import fail.
FAKE_PSYCOPG2 = '''import json, os
if os.environ.get('FAKE_PG_MISSING'):
    raise ImportError('no psycopg2')
class OperationalError(Exception):
    pass
class Connection:
    def close(self):
        pass
def connect(**kwargs):
    with open(os.environ['FAKE_PG_LOG'], 'w') as stream:
        json.dump(kwargs, stream)
    if os.environ.get('FAKE_PG_ERROR'):
        raise OperationalError(os.environ['FAKE_PG_ERROR'])
    return Connection()
'''


def account_lines(path):
    """The ODOO_DB_USER and ODOO_DB_PASSWORD assignments of an env file, in order."""
    return [line for line in path.read_text().splitlines() if line.startswith('ODOO_DB_')]


@unittest.skipUnless(shutil.which('git'), 'git is required')
class GeneratedAccountTests(unittest.TestCase):
    setUp = test_setup.SetupTests.setUp
    git = test_setup.SetupTests.git
    odoo_source = test_setup.SetupTests.odoo_source
    module = test_setup.SetupTests.module
    setup_cmd = test_setup.SetupTests.setup_cmd
    tree = test_setup.SetupTests.tree
    existing_workspace = test_setup.SetupTests.existing_workspace

    def test_setup_generates_the_account_in_one_0600_file_and_never_prints_it(self):
        result = self.setup_cmd('--apply', '--community', str(self.source), '--no-enterprise', *test_setup.CREATE)
        self.assertEqual((result.returncode, result.stderr), (0, ''), result.stdout)
        config = self.checkout / '.oasis/config'
        env_file, conf = config / '.env', config / 'odoo.conf'
        user, password = account_lines(env_file)
        self.assertEqual(user, 'ODOO_DB_USER=oasis_shop')
        self.assertRegex(password, r'\AODOO_DB_PASSWORD=[A-Za-z0-9_-]{32}\Z')
        self.assertEqual(env_file.stat().st_mode & 0o777, 0o600)
        self.assertNotIn(password.split('=', 1)[1], result.stdout + result.stderr)
        self.assertIn(f'create {env_file} (mode 0600): ODOO_DB_USER oasis_shop and a generated ODOO_DB_PASSWORD\n',
                      result.stdout)
        # odoo.conf stays path-free and password-free: Odoo gets the account of the env file.
        text = conf.read_text()
        self.assertTrue(text.endswith('db_user =\ndb_password =\n'), text)
        self.assertIn(f'; db_user and db_password stay empty: oasis passes ODOO_DB_USER and ODOO_DB_PASSWORD of '
                      f'{env_file} to Odoo as PGUSER and PGPASSWORD.\n', text)
        # Nothing to fill in by hand: no step asks for a password.
        self.assertNotIn('fill in', result.stdout)
        self.assertNotIn('password', result.stdout.split('next steps:')[1].lower())
        # Every new workspace gets its own password.
        other = self.scratch / 'other'
        shutil.copytree(self.checkout, other, symlinks=True,
                        ignore=shutil.ignore_patterns('.oasis', 'oasis-workspace.toml'))
        self.checkout = other
        again = self.setup_cmd('--apply', *test_setup.CREATE)
        self.assertEqual((again.returncode, again.stderr), (0, ''), again.stdout)
        self.assertNotEqual(account_lines(other / '.oasis/config/.env')[1], password)

    def test_a_kept_odoo_conf_with_an_account_gives_the_new_env_file_its_values(self):
        project = self.existing_workspace()
        conf, env_file = project / 'config/odoo.conf', project / 'config/.env'
        for options, expected in (
                (f'db_user = legacy\ndb_password = {MARKER}\n', ['ODOO_DB_USER=legacy', f'ODOO_DB_PASSWORD={MARKER}']),
                (f'db_password = {MARKER} $x\n', ['ODOO_DB_USER=oasis_shop', f"ODOO_DB_PASSWORD='{MARKER} $x'"])):
            with self.subTest(options=options):
                env_file.unlink(missing_ok=True)
                conf.write_text(f'[options]\ndb_port = 6543\n{options}')
                result = self.setup_cmd('--apply')
                self.assertEqual((result.returncode, result.stderr), (0, ''), result.stdout)
                self.assertNotIn(MARKER, result.stdout)
                self.assertEqual(account_lines(env_file), expected)
                self.assertEqual(env_file.stat().st_mode & 0o777, 0o600)
                source = (f'ODOO_DB_USER from db_user of {conf}' if 'db_user' in options
                          else 'ODOO_DB_USER oasis_shop')
                self.assertIn(f'create {env_file} (mode 0600): {source} and ODOO_DB_PASSWORD from db_password of '
                              f'{conf}\n', result.stdout)
                # The move (S2, "Los respeta y ofrece migrar"): the env file now holds odoo.conf's account, so
                # setup removes it from odoo.conf, those lines only.
                moved = 'db_user and db_password' if 'db_user' in options else 'db_password'
                lines = 'those lines' if 'db_user' in options else 'that line'
                self.assertIn(f'remove {moved} from {conf} ({lines} only): {env_file} holds the same account, which '
                              'oasis passes to Odoo\n', result.stdout)
                self.assertEqual(conf.read_text(), '[options]\ndb_port = 6543\n')
        # A value the env file cannot hold is refused before anything is written.
        env_file.unlink()
        conf.write_text("[options]\ndb_port = 6543\ndb_password = it's \"two\"\n")
        before = self.tree()
        result = self.setup_cmd('--apply')
        self.assertEqual((result.returncode, result.stdout), (2, ''))
        self.assertEqual(result.stderr, f'ERROR: Cannot copy db_password of {conf} to {env_file}: docker compose would '
                                        f'not read its value as written; write {env_file} yourself, then run oasis '
                                        'setup again.\n')
        self.assertEqual(self.tree(), before)


    # -- an existing project (S2: "Los respeta y ofrece migrar") ----------------------------------

    def test_setup_moves_an_odoo_conf_account_the_env_file_holds_keeping_every_other_byte(self):
        project = self.existing_workspace()
        conf, env_file = project / 'config/odoo.conf', project / 'config/.env'
        kept = (f'; my odoo.conf\n[options]\ndb_host = 127.0.0.1\ndb_port = 6543\nDB_USER = legacy\n'
                f'admin_passwd = {MARKER}-admin\n')
        conf.write_text(f'{kept}db_password = {MARKER}\n; db_password = old\n\n[other]\ndb_user = x\n')
        conf.chmod(0o640)
        env_text = f"# mine\nODOO_DB_USER=legacy\nexport ODOO_DB_PASSWORD='{MARKER}' # kept\n"
        env_file.write_text(env_text)
        line = (f'remove db_user and db_password from {conf} (those lines only): {env_file} holds the same account, '
                'which oasis passes to Odoo\n')
        before = self.tree()
        plan = self.setup_cmd()
        self.assertEqual((plan.returncode, plan.stderr), (0, ''))
        self.assertIn(f'kept {conf}\n', plan.stdout)
        self.assertIn(f'kept {env_file}\n{line}', plan.stdout)
        self.assertNotIn(MARKER, plan.stdout)
        self.assertEqual(self.tree(), before)
        result = self.setup_cmd('--apply')
        self.assertEqual((result.returncode, result.stderr), (0, ''), result.stdout)
        self.assertIn(line, result.stdout)
        self.assertNotIn(MARKER, result.stdout)
        self.assertEqual(conf.read_text(), f'{kept.replace("DB_USER = legacy" + chr(10), "")}; db_password = old\n\n'
                                           '[other]\ndb_user = x\n')
        self.assertEqual(conf.stat().st_mode & 0o777, 0o640)
        self.assertEqual(env_file.read_text(), env_text)
        # Moved: a second run proposes nothing more.
        again = self.setup_cmd('--apply')
        self.assertEqual((again.returncode, again.stderr), (0, ''))
        self.assertNotIn('remove db_', again.stdout)
        self.assertIn('nothing to set up', again.stdout)

    def test_setup_warns_and_changes_nothing_when_the_env_file_differs_or_lacks_the_account(self):
        project = self.existing_workspace()
        conf, env_file = project / 'config/odoo.conf', project / 'config/.env'
        conf_text = f'[options]\ndb_port = 6543\ndb_user = legacy\ndb_password = {MARKER}\n'
        tail = (f': both files kept, and Odoo keeps connecting with the account of {conf}; setup moves it to '
                f'{env_file} only when both hold the same values\n')
        for env_text, details in (
                (f'ODOO_DB_USER=legacy\nODOO_DB_PASSWORD={MARKER}-other\n', 'db_password (another value)'),
                (f'ODOO_DB_PASSWORD={MARKER}\n', 'db_user (not set)'),
                (f'ODOO_DB_USER=mine\nODOO_DB_PASSWORD="${{SECRET}}"\n', 'db_user and db_password (another value)')):
            with self.subTest(env_text=env_text):
                conf.write_text(conf_text)
                env_file.write_text(env_text)
                result = self.setup_cmd('--apply')
                self.assertEqual((result.returncode, result.stderr), (0, ''), result.stdout)
                self.assertIn(f'kept {env_file}\nWARN: {env_file} does not hold the account {conf} sets: '
                              f'{details}{tail}', result.stdout)
                self.assertNotIn('remove db_', result.stdout)
                self.assertNotIn(MARKER, result.stdout)
                self.assertEqual((conf.read_text(), env_file.read_text()), (conf_text, env_text))

    def test_setup_fills_the_empty_account_of_a_kept_env_file_keeping_every_other_byte(self):
        project = self.existing_workspace()
        conf, env_file = project / 'config/odoo.conf', project / 'config/.env'
        password = r'[A-Za-z0-9_-]{32}'
        both = 'ODOO_DB_USER and ODOO_DB_PASSWORD'
        generated = 'ODOO_DB_USER oasis_shop and a generated ODOO_DB_PASSWORD'
        for conf_text, env_text, names, described, expected, moved in (
                ('', '# mine\nODOO_DB_USER=\nOTHER=kept\nexport ODOO_DB_PASSWORD="" # fill in\n', both, generated,
                 rf'# mine\nODOO_DB_USER=oasis_shop\nOTHER=kept\nexport ODOO_DB_PASSWORD={password} # fill in\n',
                 None),
                ('', 'ODOO_DB_USER=mine\nODOO_DB_PASSWORD=\n', 'ODOO_DB_PASSWORD', 'a generated ODOO_DB_PASSWORD',
                 rf'ODOO_DB_USER=mine\nODOO_DB_PASSWORD={password}\n', None),
                # A value that is only a comment is empty, as doctor reads it (FAIL env_file=empty).
                ('', 'ODOO_DB_USER= # comment\nODOO_DB_PASSWORD=\t# fill in\n', both, generated,
                 rf'ODOO_DB_USER=oasis_shop # comment\nODOO_DB_PASSWORD={password}\t# fill in\n', None),
                ('db_user = legacy\n', 'ODOO_DB_USER=\nODOO_DB_PASSWORD=\n', both,
                 f'ODOO_DB_USER from db_user of {conf} and a generated ODOO_DB_PASSWORD',
                 rf'ODOO_DB_USER=legacy\nODOO_DB_PASSWORD={password}\n', 'db_user')):
            with self.subTest(env_text=env_text, conf_text=conf_text):
                conf.write_text(f'[options]\ndb_port = 6543\n{conf_text}')
                env_file.write_text(env_text)
                env_file.chmod(0o644)
                line = f'fill {names} in {env_file} (mode 0600; every other line kept): {described}\n'
                plan = self.setup_cmd()
                self.assertEqual((plan.returncode, plan.stderr), (0, ''))
                self.assertIn(line, plan.stdout)
                self.assertEqual(env_file.read_text(), env_text)
                result = self.setup_cmd('--apply')
                self.assertEqual((result.returncode, result.stderr), (0, ''), result.stdout)
                self.assertIn(line, result.stdout)
                text = env_file.read_text()
                self.assertRegex(text, rf'\A{expected}\Z')
                self.assertEqual(env_file.stat().st_mode & 0o777, 0o600)
                value = re.search(rf'ODOO_DB_PASSWORD=({password})', text).group(1)
                self.assertNotIn(value, result.stdout + plan.stdout)
                if moved:
                    self.assertIn(f'remove {moved} from {conf} (that line only): {env_file} holds the same account, '
                                  'which oasis passes to Odoo\n', result.stdout)
                self.assertEqual(conf.read_text(), '[options]\ndb_port = 6543\n')
        # Filled: a second run keeps it.
        again = self.setup_cmd('--apply')
        self.assertEqual((again.returncode, again.stderr), (0, ''))
        self.assertIn(f'kept {env_file}\n', again.stdout)
        self.assertNotIn('fill ', again.stdout)

    def test_setup_keeps_a_tilde_or_null_account_value_as_a_value(self):
        # In an env file `~` and `null` are the words themselves (docker compose reads them so): not empty.
        project = self.existing_workspace()
        conf, env_file = project / 'config/odoo.conf', project / 'config/.env'
        conf.write_text('[options]\ndb_port = 6543\n')
        for env_text in ('ODOO_DB_USER=~\nODOO_DB_PASSWORD=null\n', 'ODOO_DB_USER=null # mine\nODOO_DB_PASSWORD=~\n'):
            with self.subTest(env_text=env_text):
                env_file.write_text(env_text)
                env_file.chmod(0o600)
                result = self.setup_cmd('--apply')
                self.assertEqual((result.returncode, result.stderr), (0, ''), result.stdout)
                self.assertIn(f'kept {env_file}\n', result.stdout)
                self.assertNotIn('fill ', result.stdout)
                self.assertNotIn(f'WARN: {env_file}', result.stdout)
                self.assertEqual(env_file.read_text(), env_text)

    def test_setup_leaves_an_env_file_that_declares_no_account_unchanged_and_warns(self):
        project = self.existing_workspace()
        conf, env_file = project / 'config/odoo.conf', project / 'config/.env'
        warning = (f'WARN: {env_file} sets neither ODOO_DB_USER nor ODOO_DB_PASSWORD: setup leaves {env_file} unchanged '
                   '(an existing file is respected); to use the account oasis generates, add the empty lines '
                   'ODOO_DB_USER= and ODOO_DB_PASSWORD= to it, then run oasis setup --apply\n')
        for conf_text, env_text in (('', f'# mine\nPOSTGRES_PASSWORD={MARKER}\nOTHER=kept'), ('', ''),
                                    (f'db_user = legacy\ndb_password = {MARKER}\n', '# mine\n')):
            with self.subTest(env_text=env_text, conf_text=conf_text):
                conf.write_text(f'[options]\ndb_port = 6543\n{conf_text}')
                env_file.write_text(env_text)
                env_file.chmod(0o644)
                for args in ((), ('--apply',)):
                    result = self.setup_cmd(*args)
                    self.assertEqual((result.returncode, result.stderr), (0, ''), result.stdout)
                    self.assertIn(f'kept {env_file}\n{warning}', result.stdout)
                    self.assertNotIn('fill ', result.stdout)
                    self.assertNotIn('remove db_', result.stdout)
                    self.assertNotIn(MARKER, result.stdout)
                    self.assertEqual(env_file.read_text(), env_text)
                    self.assertEqual(env_file.stat().st_mode & 0o777, 0o644)
                    self.assertEqual(conf.read_text(), f'[options]\ndb_port = 6543\n{conf_text}')


def load_tool(name):
    """A tool of the bundle as a module, loaded from its file (python3 -I runs them off sys.path)."""
    spec = importlib.util.spec_from_file_location(f'oasis_test_{name}', ROOT / 'tools' / f'{name}.py')
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


class EmptyAccountValueTests(unittest.TestCase):
    """setup fills exactly the account values doctor reports empty (FAIL env_file=empty)."""

    def test_setup_and_doctor_agree_on_which_account_values_are_empty(self):
        account, doctor = load_tool('db_account'), load_tool('doctor')
        for raw, empty in (('', True), ('   ', True), (' # comment', True), ('\t# comment', True), ('""', True),
                           ("''", True), ('"" # comment', True), ("'' # comment", True), ('~', False),
                           ('null', False), ('~ # comment', False), ('#x', False), ('v # comment', False),
                           ("'a # b'", False), ('" "', False)):
            with self.subTest(raw=raw):
                values = account.text_values(f'export ODOO_DB_USER={raw}\nODOO_DB_PASSWORD=x\n', account.account_names())
                self.assertEqual(account.fill_names(values), ['ODOO_DB_USER'] if empty else [])
                self.assertEqual(doctor.empty_value(raw), empty)


class AuthenticationFixTests(unittest.TestCase):
    """db_account.py fix: a port mapping oasis cannot read never decides which server refused the account."""

    def setUp(self):
        self.scratch = Path(tempfile.mkdtemp(prefix='oasis-credentials-')).resolve()
        self.addCleanup(shutil.rmtree, self.scratch, ignore_errors=True)
        self.conf, self.env_file = self.scratch / 'odoo.conf', self.scratch / '.env'
        self.compose = self.scratch / 'compose.yml'
        self.conf.write_text('[options]\ndb_host = 127.0.0.1\ndb_port = 6001\n')
        self.env_file.write_text(f'ODOO_DB_USER=oasis_cc\nODOO_DB_PASSWORD={MARKER}\n')

    def fix(self, ports):
        if ports is not None:
            self.compose.write_text(f'name: cc-shop\nservices:\n  db:\n    image: postgres:17\n{ports}')
        result = subprocess.run([sys.executable, '-B', str(ACCOUNT), 'fix', str(self.conf), str(self.env_file),
                                 str(self.compose), 'oasis', str(self.scratch)], capture_output=True, text=True,
                                timeout=60)
        self.assertEqual((result.returncode, result.stderr), (0, ''))
        self.assertNotIn(MARKER, result.stdout)
        return result.stdout

    def unread(self, why, where='db_host 127.0.0.1, db_port 6001', confirm=True):
        command = ['oasis', '--project', str(self.scratch), 'recreate-postgres-volume']
        command += ['--confirm', 'cc-shop'] if confirm else []
        return (f'the PostgreSQL that {self.conf} names ({where}) refuses the account Odoo uses, and oasis could not '
                f'read the port {self.compose} publishes to 5432 ({why}), so it cannot tell whether that server is the '
                f'service of {self.compose}: if it is, {shlex.join(command)} recreates its volume with the account of '
                f'{self.env_file} (Tier B: it deletes every database of the service); if it is not, correct that '
                'account on that server; then run oasis doctor again\n')

    def test_a_port_mapping_oasis_cannot_read_names_both_fixes(self):
        entry = 'an entry other than - [<address>:]<port>:5432'
        for ports, why in (
                ('    ports:\n      - target: 5432\n        published: 6001\n', entry),
                ('    ports:\n      - published: 6001\n        target: 5432\n', entry),
                ("    ports:\n      - '${DB_PORT:-6001}:5432'\n", entry),
                ('    ports:\n      - "6001-6002:5432"\n', entry),
                ('    ports:\n      - 5432\n', entry),
                ("    ports:\n      - '127.0.0.1:6001:5432'\n      - '${OTHER}:5432'\n", entry),
                ("    ports:\n      - '127.0.0.1:6001:5432'\n      - '127.0.0.1:6002:5432'\n", 'several ports')):
            with self.subTest(ports=ports):
                self.assertEqual(self.fix(ports), self.unread(why))
        # The host alone does not decide either while the mapping is unread.
        self.conf.write_text('[options]\ndb_host = db.example.invalid\ndb_port = 6001\n')
        self.assertEqual(self.fix("    ports:\n      - '${DB_PORT:-6001}:5432'\n"),
                         self.unread(entry, where='db_host db.example.invalid, db_port 6001'))

    @unittest.skipIf(os.geteuid() == 0, 'root reads any file')
    def test_an_unreadable_compose_file_names_both_fixes(self):
        self.compose.write_text("name: cc-shop\nservices:\n  db:\n    ports:\n      - '127.0.0.1:6001:5432'\n")
        self.compose.chmod(0)
        self.addCleanup(self.compose.chmod, 0o600)
        self.assertEqual(self.fix(None), self.unread('it cannot be read', confirm=False))

    def test_a_mapping_it_reads_keeps_its_fix(self):
        recreate = shlex.join(['oasis', '--project', str(self.scratch), 'recreate-postgres-volume', '--confirm',
                               'cc-shop'])
        local = (f'the PostgreSQL that {self.conf} names refuses the account Odoo uses: its volume was initialized with '
                 f'other credentials than {self.env_file}; {recreate} recreates it with them (Tier B: it deletes every '
                 'database of the service)\n')
        for ports in ("    ports:\n      - '127.0.0.1:6001:5432'\n",
                      "    ports:\n      - '127.0.0.1:6001:5432'\n      - '6001:5432/tcp'  # same port\n"):
            with self.subTest(ports=ports):
                self.assertEqual(self.fix(ports), local)
        other = ('the PostgreSQL that {conf} names (db_host 127.0.0.1, db_port 6001) refuses the account Odoo uses, and '
                 'it is not the service of {compose} ({service}): correct that account on that server, or set db_host '
                 '= 127.0.0.1 and the db_port {compose} publishes in {conf}; then run oasis doctor again\n')
        self.assertEqual(self.fix("    ports:\n      - '127.0.0.1:6002:5432'\n"),
                         other.format(conf=self.conf, compose=self.compose, service='published on 127.0.0.1:6002'))
        # Only the entries under ports: are judged: expose and environment items that name 5432 next to a mapping
        # it reads keep its fix.
        for others in ('    expose:\n      - "5432"\n',
                       '    environment:\n      - PGPORT=5432\n      - POSTGRES_HOST_AUTH_METHOD=md5\n',
                       '    healthcheck:\n      test:\n        - CMD-SHELL\n        - pg_isready -p 5432\n',
                       '    labels:\n      - target: 5432\n'):
            for order in ('before', 'after'):
                with self.subTest(others=others, order=order):
                    ports = "    ports:\n      - '127.0.0.1:6001:5432'\n"
                    self.assertEqual(self.fix(others + ports if order == 'before' else ports + others), local)
        # A ports list at the key's own indentation, and its long syntax, are still judged.
        self.assertEqual(self.fix("    ports:\n    - '127.0.0.1:6001:5432'\n    expose:\n    - '5432'\n"), local)
        self.assertEqual(self.fix('    ports:\n    - target: 5432\n      published: 6001\n'),
                         self.unread('an entry other than - [<address>:]<port>:5432'))
        self.assertEqual(self.fix("    ports:  # published\n\n      # the database\n      - '${DB_PORT}:5432'\n"),
                         self.unread('an entry other than - [<address>:]<port>:5432'))
        # A ports key with a YAML tag (compose's !override, !reset) or an anchor is still the ports key.
        for key in ('ports: !override', 'ports: &db_ports', 'ports: &db_ports !override  # merged', "'ports': !reset"):
            with self.subTest(key=key):
                self.assertEqual(self.fix(f"    {key}\n      - '${{DB_PORT}}:5432'\n"),
                                 self.unread('an entry other than - [<address>:]<port>:5432'))
                self.assertEqual(self.fix(f"    {key}\n      - '127.0.0.1:6001:5432'\n"), local)
        # No entry names the container's port: nothing is published to 5432.
        self.assertEqual(self.fix('    environment:\n      POSTGRES_DB: postgres\n'),
                         other.format(conf=self.conf, compose=self.compose, service='no port published to 5432 found'))


class LaunchTests(unittest.TestCase):
    """Every command that starts Odoo passes the env file's account through the environment."""
    setUp_fixture = lifecycle.LifecycleTests.setUp
    invoke = lifecycle.LifecycleTests.invoke

    def setUp(self):
        self.setUp_fixture()
        for name in ('PGUSER', 'PGPASSWORD'):
            self.env.pop(name, None)
        # The fake Odoo also records the account it was given, and whether argv holds the password.
        self.python.write_text(self.python.read_text().replace(
            'printf "odoo %s\\n" "$*" >> "$FAKE_LOG"\n',
            'printf "odoo %s\\n" "$*" >> "$FAKE_LOG"\n'
            'printf "account user=%s password=%s\\n" "${PGUSER-<unset>}" "${PGPASSWORD-<unset>}" >> "$FAKE_LOG"\n'))
        (self.root / 'dev/.env').write_text(f"ODOO_DB_USER=oasis_cc\nODOO_DB_PASSWORD='{MARKER} $x'\n")
        # install-module runs on an existing database only (v0.20.0 S12: it never creates one).
        self.env['FAKE_EXISTS'] = '1'

    def accounts(self):
        lines = self.commands.read_text().splitlines()
        for line in lines:
            if line.startswith(('odoo ', 'docker ')):
                self.assertNotIn(MARKER, line)
        return [line for line in lines if line.startswith('account ')]

    def test_odoo_gets_the_env_file_account_through_the_environment(self):
        result = self.invoke('install-module', 'coffee')
        self.assertEqual((result.returncode, result.stdout, result.stderr), (0, '', ''))
        self.assertEqual(self.accounts(), [f'account user=oasis_cc password={MARKER} $x'])
        self.env['FAKE_EXISTS'] = '1'
        self.commands.unlink()
        result = self.invoke('odoo-shell', 'cc_dev_coffee', input='print(1)\n')
        self.assertEqual((result.returncode, result.stderr), (0, ''))
        self.assertEqual(self.accounts(), [f'account user=oasis_cc password={MARKER} $x'])

    def test_what_odoo_conf_sets_is_kept_and_not_exported(self):
        conf = self.root / 'dev/odoo.conf'
        for options, expected in (('db_user = mine\ndb_password = theirs\n', 'user=<unset> password=<unset>'),
                                  ('db_user = mine\ndb_password =\n', f'user=<unset> password={MARKER} $x'),
                                  ('db_password = False\n', f'user=oasis_cc password={MARKER} $x')):
            with self.subTest(options=options):
                conf.write_text(lifecycle.conf_text(options))
                self.commands.unlink(missing_ok=True)
                result = self.invoke('install-module', 'coffee')
                self.assertEqual((result.returncode, result.stdout, result.stderr), (0, '', ''))
                self.assertEqual(self.accounts(), [f'account {expected}'])

    def test_a_value_oasis_cannot_read_as_compose_does_is_refused_never_exported(self):
        env_file = self.root / 'dev/.env'
        for text, names in ((f'ODOO_DB_USER=oasis_cc\nODOO_DB_PASSWORD=${{SECRET}}{MARKER}\n', 'ODOO_DB_PASSWORD'),
                            (f'ODOO_DB_USER="$USER"\nODOO_DB_PASSWORD="{MARKER}\\n"\n',
                             'ODOO_DB_USER and ODOO_DB_PASSWORD')):
            with self.subTest(text=text):
                env_file.write_text(text)
                self.commands.unlink(missing_ok=True)
                result = self.invoke('install-module', 'coffee')
                self.assertEqual((result.returncode, result.stdout), (2, ''))
                self.assertEqual(result.stderr, (
                    f'ERROR: {env_file} sets {names} with compose interpolation ($) or a double-quoted escape (\\), '
                    'which oasis does not read: write the value literally in single quotes.\n'))
                self.assertNotIn(MARKER, result.stderr)
                self.assertEqual(self.accounts(), [])
        # What odoo.conf sets is not read from the env file: nothing to refuse.
        (self.root / 'dev/odoo.conf').write_text(lifecycle.conf_text('db_user = mine\ndb_password = theirs\n'))
        self.commands.unlink(missing_ok=True)
        result = self.invoke('install-module', 'coffee')
        self.assertEqual((result.returncode, result.stdout, result.stderr), (0, '', ''))
        self.assertEqual(self.accounts(), ['account user=<unset> password=<unset>'])

    def test_exports_are_refused_on_a_terminal(self):
        master, slave = pty.openpty()
        self.addCleanup(os.close, master)
        try:
            result = subprocess.run([sys.executable, '-I', '-B', str(ACCOUNT), 'exports', str(self.root / 'dev/odoo.conf'),
                                     str(self.root / 'dev/.env')], stdout=slave, stderr=subprocess.PIPE, text=True)
        finally:
            os.close(slave)
        self.assertEqual(result.returncode, 2)
        self.assertEqual(result.stderr, 'ERROR: db_account.py exports writes the account only to a pipe, never to '
                                        'a terminal.\n')


class ProbeTests(unittest.TestCase):
    """db_account.py probe: Odoo's account against the PostgreSQL odoo.conf names, one word out."""

    def setUp(self):
        self.scratch = Path(tempfile.mkdtemp(prefix='oasis-credentials-')).resolve()
        self.addCleanup(shutil.rmtree, self.scratch, ignore_errors=True)
        (self.scratch / 'fake/psycopg2').mkdir(parents=True)
        (self.scratch / 'fake/psycopg2/__init__.py').write_text(FAKE_PSYCOPG2)
        self.conf, self.env_file = self.scratch / 'odoo.conf', self.scratch / 'account'
        self.conf.write_text('[options]\ndb_host = 127.0.0.1\ndb_port = 6001\ndb_user =\ndb_password =\n')
        self.env_file.write_text(f'# account\nexport ODOO_DB_USER="oasis_cc"\nODOO_DB_PASSWORD={MARKER} # kept\n')
        self.log = self.scratch / 'connect.json'
        self.env = {key: value for key, value in os.environ.items() if not key.startswith(('PG', 'FAKE_'))}
        self.env.update(PYTHONPATH=str(self.scratch / 'fake'), FAKE_PG_LOG=str(self.log), PYTHONDONTWRITEBYTECODE='1')

    def probe(self, **env):
        result = subprocess.run([sys.executable, '-B', str(ACCOUNT), 'probe', str(self.conf), str(self.env_file)],
                                capture_output=True, text=True, env={**self.env, **env}, timeout=60)
        self.assertNotIn(MARKER, result.stdout + result.stderr)
        return result

    def test_it_connects_with_odoos_account(self):
        result = self.probe()
        self.assertEqual((result.returncode, result.stdout, result.stderr), (0, 'ready\n', ''))
        self.assertEqual(json.loads(self.log.read_text()), {
            'dbname': 'postgres', 'connect_timeout': 5, 'host': '127.0.0.1', 'port': '6001', 'user': 'oasis_cc',
            'password': MARKER})
        # What odoo.conf sets wins, as Odoo reads it; an empty db_host is left to libpq, like Odoo.
        self.conf.write_text('[options]\ndb_port = 6001\ndb_user = mine\ndb_password = theirs\n')
        self.assertEqual(self.probe().stdout, 'ready\n')
        self.assertEqual(json.loads(self.log.read_text()), {
            'dbname': 'postgres', 'connect_timeout': 5, 'port': '6001', 'user': 'mine', 'password': 'theirs'})

    def test_each_failure_is_one_word_without_the_server_message(self):
        for message, word in (('FATAL:  password authentication failed for user "oasis_cc"', 'authentication_failed'),
                              ('FATAL:  role "oasis_cc" does not exist', 'authentication_failed'),
                              ('fe_sendauth: no password supplied', 'authentication_failed'),
                              ('connection to server at "127.0.0.1", port 6001 failed: Connection refused',
                               'not_running'),
                              ('could not connect to server: No such file or directory', 'not_running'),
                              ('timeout expired', 'not_running'),
                              ('FATAL:  the database system is starting up', 'failed')):
            with self.subTest(message=message):
                result = self.probe(FAKE_PG_ERROR=message)
                self.assertEqual((result.returncode, result.stdout, result.stderr), (0, f'{word}\n', ''))
        result = self.probe(FAKE_PG_MISSING='1')
        self.assertEqual((result.returncode, result.stdout, result.stderr), (0, 'no_driver\n', ''))


class CheckEnvironmentConnectionTests(unittest.TestCase):
    """check-environment --full connects with Odoo's account (tools/db_account.py probe), not psql."""
    setUp = lifecycle.LifecycleTests.setUp
    invoke = lifecycle.LifecycleTests.invoke

    def prepare(self):
        import test_environment
        test_environment.EnvironmentTests.prepare(self)
        test_environment.EnvironmentTests.running_database(self)
        # odoo.conf names the endpoint the compose service publishes.
        (self.root / 'dev/compose.yml').write_text("name: cc-shop\nservices:\n  db:\n    image: postgres:17\n"
                                                   "    ports:\n      - '127.0.0.1:6001:5432'\n")
        (self.root / 'dev/odoo.conf').write_text(lifecycle.conf_text('db_host = 127.0.0.1\ndb_port = 6001\n'))

    def test_an_authentication_failure_names_the_volume_recreate(self):
        self.prepare()
        self.env['FAKE_CONNECTION'] = 'authentication_failed'
        result = self.invoke('check-environment', '--full')
        self.assertEqual(result.returncode, 1)
        self.assertIn('PASS postgres_service=running\n', result.stdout)
        command = shlex.join(['oasis', '--project', str(self.root), 'recreate-postgres-volume', '--confirm', 'cc-shop'])
        self.assertTrue(result.stderr.endswith(
            'FAIL postgres_connection=authentication_failed\n'
            f'  fix: the PostgreSQL that {self.root / "dev/odoo.conf"} names refuses the account Odoo uses: its volume '
            f'was initialized with other credentials than {self.root / "dev/.env"}; {command} recreates it with them '
            '(Tier B: it deletes every database of the service)\n'), result.stderr)
        self.assertNotIn('exec psql', self.commands.read_text())
        self.env['FAKE_CONNECTION'] = 'ready'
        result = self.invoke('check-environment', '--full')
        self.assertIn('PASS postgres_connection=ready\n', result.stdout)


    def test_another_server_than_the_compose_service_is_not_offered_the_volume_recreate(self):
        self.prepare()
        self.env['FAKE_CONNECTION'] = 'authentication_failed'
        conf, compose = self.root / 'dev/odoo.conf', self.root / 'dev/compose.yml'
        for options, where in (('db_host = db.example.invalid\ndb_port = 6001\n', 'db_host db.example.invalid, db_port 6001'),
                               ('db_host = localhost\ndb_port = 6002\n', 'db_host localhost, db_port 6002'),
                               ('db_port = 6001\n', 'no db_host, db_port 6001')):
            with self.subTest(options=options):
                conf.write_text(lifecycle.conf_text(options))
                result = self.invoke('check-environment', '--full')
                self.assertEqual(result.returncode, 1)
                self.assertTrue(result.stderr.endswith(
                    'FAIL postgres_connection=authentication_failed\n'
                    f'  fix: the PostgreSQL that {conf} names ({where}) refuses the account Odoo uses, and it is not '
                    f'the service of {compose} (published on 127.0.0.1:6001): correct that account on that server, or '
                    f'set db_host = 127.0.0.1 and the db_port {compose} publishes in {conf}; then run oasis doctor '
                    'again\n'), result.stderr)
        # localhost names the published endpoint too.
        conf.write_text(lifecycle.conf_text('db_host = localhost\ndb_port = 6001\n'))
        self.assertIn('recreate-postgres-volume --confirm cc-shop', self.invoke('check-environment', '--full').stderr)

    def test_each_word_of_the_probe_is_checked_and_an_unknown_one_is_unchecked(self):
        self.prepare()
        # An empty answer stays empty (the fixture's default answer is ready).
        self.python.write_text(self.python.read_text().replace('${FAKE_CONNECTION:-ready}', '${FAKE_CONNECTION-ready}'))
        for answer, word in (('not_running', 'not_running'), ('no_driver', 'no_driver'), ('failed', 'failed'),
                             ('', 'unchecked'), ('Traceback (most recent call last):', 'unchecked'),
                             ('ready now', 'unchecked')):
            with self.subTest(answer=answer):
                self.env['FAKE_CONNECTION'] = answer
                result = self.invoke('check-environment', '--full')
                self.assertEqual(result.returncode, 1)
                self.assertIn(f'FAIL postgres_connection={word}\n', result.stderr)
                self.assertNotIn('  fix:', result.stderr)
                self.assertNotIn('PASS postgres_connection', result.stdout)

    def test_an_env_file_value_oasis_cannot_read_fails_naming_the_file_and_variable(self):
        self.prepare()
        env_file = self.root / 'dev/.env'
        env_file.write_text(f'ODOO_DB_USER=oasis_cc\nODOO_DB_PASSWORD="{MARKER}\\t$x"\n')
        fix = (f'FAIL env_file=unsupported_value ODOO_DB_PASSWORD\n  fix: write ODOO_DB_PASSWORD in {env_file} '
               'literally in single quotes: oasis does not read compose interpolation ($) or double-quoted escapes '
               '(\\), so Odoo would get another credential\n')
        for mode in ('--quick', '--full'):
            with self.subTest(mode=mode):
                result = self.invoke('check-environment', mode)
                self.assertEqual(result.returncode, 1)
                self.assertIn(fix, result.stderr)
                self.assertNotIn(MARKER, result.stdout + result.stderr)
                # The probe does not run with a credential oasis cannot read.
                self.assertNotIn('postgres_connection=', result.stderr)
                self.assertNotIn('PASS postgres_connection', result.stdout)


class RecreateVolumeTests(unittest.TestCase):
    """recreate-postgres-volume is Tier B: --confirm <compose project>, else the plan and a refusal."""
    setUp_fixture = lifecycle.LifecycleTests.setUp

    def setUp(self):
        self.setUp_fixture()
        (self.root / 'dev/compose.yml').write_text("name: 'cc-shop'\nservices:\n  db:\n    image: postgres:17\n")
        (self.root / 'dev/.env').write_text(f'ODOO_DB_USER=oasis_cc\nODOO_DB_PASSWORD={MARKER}\n')
        self.env.pop('COMPOSE_PROJECT_NAME', None)
        # FAKE_DOWN_FAIL and FAKE_UP_FAIL make `compose down` and `compose up` fail (exit 1).
        docker = self.bindir / 'docker'
        head, tail = docker.read_text().rsplit('exit 0\n', 1)
        docker.write_text(head + 'case "$*" in\n'
                          '  *" down -v") [ -z "${FAKE_DOWN_FAIL:-}" ] || exit 1 ;;\n'
                          '  *" up -d "*) [ -z "${FAKE_UP_FAIL:-}" ] || exit 1 ;;\n'
                          'esac\nexit 0\n' + tail)

    def compose(self, *args):
        """A docker compose call as the fake docker records it: always with the confirmed project."""
        return ' '.join(['docker compose --env-file', str(self.root / 'dev/.env'), '-f', str(self.root / 'dev/compose.yml'),
                         '-p', 'cc-shop', *args])

    def start_command(self):
        # v0.16.0 S6: setup-postgres, which names no env file (a harness may refuse a command that does); it runs
        # the same compose project, since a COMPOSE_PROJECT_NAME that selects another one was refused first.
        return shlex.join(['oasis', '--project', str(self.root), 'setup-postgres'])

    def cli(self, *args, command='recreate-postgres-volume'):
        result = subprocess.run([sys.executable, '-B', str(ROOT / 'oasis'), '--project', str(self.root),
                                 command, *args], text=True, capture_output=True, cwd=self.root,
                                env=self.env)
        self.assertNotIn(MARKER, result.stdout + result.stderr)
        return result

    def calls(self):
        return self.commands.read_text().splitlines() if self.commands.exists() else []

    def plan(self):
        return (f'compose_project=cc-shop\ncompose_file={self.root / "dev/compose.yml"}\nservice=db\n'
                f'account={self.root / "dev/.env"}\n'
                'deletes=the containers, networks and volumes of compose project cc-shop (docker compose down -v: '
                'every named volume of its compose file and every anonymous volume of its containers), so every '
                'database of its PostgreSQL, the trash included\n')

    def test_without_the_exact_compose_project_it_prints_the_plan_and_changes_nothing(self):
        command = shlex.join(['oasis', '--project', str(self.root), 'recreate-postgres-volume', '--confirm', 'cc-shop'])
        result = self.cli()
        self.assertEqual((result.returncode, result.stdout, result.stderr), (2, self.plan(), (
            'ERROR: recreate-postgres-volume deletes the PostgreSQL volume of compose project cc-shop and every '
            f'database in it, then starts the service again with the account of {self.root / "dev/.env"} (Tier B: it '
            f'needs explicit confirmation); nothing changed. Run: {command}\n')))
        result = self.cli('--confirm', 'other')
        self.assertEqual((result.returncode, result.stdout, result.stderr), (2, self.plan(), (
            f'ERROR: --confirm other does not name the compose project cc-shop; nothing changed. Run: {command}\n')))
        self.assertEqual(self.calls(), [])

    def test_with_the_compose_project_it_removes_the_volume_and_starts_the_service(self):
        result = self.cli('--confirm=cc-shop')
        self.assertEqual((result.returncode, result.stderr), (0, ''))
        self.assertEqual(result.stdout, self.plan() + (
            f'Recreated the database volume of cc-shop; service db runs with the account of {self.root / "dev/.env"}.\n'))
        # The confirmed project explicitly (-p): COMPOSE_PROJECT_NAME never picks another one.
        self.assertEqual(self.calls(), [self.compose('down', '-v'), self.compose('up', '-d', '--wait', '--wait-timeout',
                                                                                 '60', 'db')])
        self.commands.unlink()
        self.env['COMPOSE_PROJECT_NAME'] = 'cc-shop'
        result = self.cli('--confirm', 'cc-shop')
        self.assertEqual((result.returncode, result.stderr), (0, ''))
        self.assertEqual(self.calls()[0], self.compose('down', '-v'))

    def test_a_compose_project_name_that_selects_another_project_is_refused(self):
        env_file = self.root / 'dev/.env'
        refusal = ('ERROR: COMPOSE_PROJECT_NAME {where} makes docker compose use the compose project other, not cc-shop '
                   f'(the top-level name: of {self.root / "dev/compose.yml"}); nothing changed: unset it or set it to '
                   'cc-shop, then run recreate-postgres-volume again.\n')
        self.env['COMPOSE_PROJECT_NAME'] = 'other'
        for args in ((), ('--confirm', 'cc-shop'), ('--confirm', 'other')):
            with self.subTest(args=args):
                result = self.cli(*args)
                self.assertEqual((result.returncode, result.stdout, result.stderr),
                                 (2, '', refusal.format(where='in the environment')))
        del self.env['COMPOSE_PROJECT_NAME']
        env_file.write_text(env_file.read_text() + 'COMPOSE_PROJECT_NAME=other # mine\n')
        result = self.cli('--confirm', 'cc-shop')
        self.assertEqual((result.returncode, result.stdout, result.stderr),
                         (2, '', refusal.format(where=f'in {env_file}')))
        self.assertEqual(self.calls(), [])

    def test_a_failure_after_the_volume_was_deleted_names_the_command_that_starts_the_service(self):
        self.env['FAKE_UP_FAIL'] = '1'
        result = self.cli('--confirm', 'cc-shop')
        self.assertEqual((result.returncode, result.stdout), (1, self.plan()))
        self.assertEqual(result.stderr, (
            'ERROR: the volume of compose project cc-shop is already gone (docker compose down -v), but service db did '
            f'not start again (exit 1): start it with {self.start_command()}\n'))
        self.assertEqual(self.calls(), [self.compose('down', '-v'), self.compose('up', '-d', '--wait', '--wait-timeout',
                                                                                 '60', 'db')])
        self.commands.unlink()
        del self.env['FAKE_UP_FAIL']
        self.env['FAKE_DOWN_FAIL'] = '1'
        result = self.cli('--confirm', 'cc-shop')
        self.assertEqual((result.returncode, result.stdout), (1, self.plan()))
        self.assertEqual(result.stderr, (
            'ERROR: docker compose down -v failed (exit 1): the volume of compose project cc-shop may already be gone; '
            f'start the service again with {self.start_command()}\n'))
        self.assertEqual(self.calls(), [self.compose('down', '-v')])

    def gone(self, status):
        return ('ERROR: the volume of compose project cc-shop is already gone (docker compose down -v), but service db '
                f'did not start again (exit {status}): start it with {self.start_command()}\n')

    def test_each_way_the_service_fails_to_start_after_the_volume_is_gone_is_reported(self):
        # wait_for_database runs in a `||` list (errexit off): each of its steps checks its own status.
        compose = self.root / 'dev/compose.yml'
        lock_dir = Path(self.env['XDG_RUNTIME_DIR']) / f'oasis-{os.getuid()}'
        lock = lock_dir / ('compose-' + hashlib.sha256(os.path.realpath(compose).encode()).hexdigest()[:16] + '.lock')
        lock_dir.mkdir(mode=0o700)
        # Another checkout holds the compose lock: timed out, no `up`.
        descriptor = os.open(lock, os.O_RDWR | os.O_CREAT, 0o600)
        self.addCleanup(os.close, descriptor)
        fcntl.flock(descriptor, fcntl.LOCK_EX)
        self.env['OASIS_COMPOSE_LOCK_TIMEOUT'] = '0.3'
        result = self.cli('--confirm', 'cc-shop')
        self.assertEqual((result.returncode, result.stdout, result.stderr), (1, self.plan(), (
            'Timed out waiting for another checkout to start the database service.\n' + self.gone(1))))
        self.assertEqual(self.calls(), [self.compose('down', '-v')])
        fcntl.flock(descriptor, fcntl.LOCK_UN)
        # The compose lock cannot be opened: runtime_state.py fails (exit 2), no `up`.
        self.commands.unlink()
        lock.unlink()
        lock.mkdir()
        result = self.cli('--confirm', 'cc-shop')
        self.assertEqual((result.returncode, result.stdout, result.stderr), (1, self.plan(), (
            f'ERROR: Cannot open the compose lock: {lock}\n' + self.gone(2))))
        self.assertEqual(self.calls(), [self.compose('down', '-v')])
        lock.rmdir()
        # Without flock, a failing `up` is reported the same way.
        self.commands.unlink()
        farm = Path(tempfile.mkdtemp(prefix='oasis-no-flock-'))
        self.addCleanup(shutil.rmtree, farm, ignore_errors=True)
        for directory in self.env['PATH'].split(':'):
            if directory and os.path.isdir(directory):
                for entry in os.scandir(directory):
                    if entry.name != 'flock' and not os.path.lexists(farm / entry.name):
                        (farm / entry.name).symlink_to(entry.path)
        self.env.update(PATH=str(farm), FAKE_UP_FAIL='1')
        result = self.cli('--confirm', 'cc-shop')
        self.assertEqual((result.returncode, result.stdout, result.stderr), (1, self.plan(), (
            'WARNING: flock not found; starting the database service without the cross-checkout lock.\n'
            + self.gone(1))))
        self.assertEqual(self.calls(), [self.compose('down', '-v'), self.compose('up', '-d', '--wait', '--wait-timeout',
                                                                                 '60', 'db')])

    def test_each_usage_error_and_a_compose_file_without_a_name_change_nothing(self):
        usage = f'Usage: {ROOT / "oasis"} [--confirm <compose project>]\n'
        for args in (('--confirm=cc-shop', '--confirm', 'cc-shop'), ('--confirm', 'cc-shop', '--confirm=cc-shop'),
                     ('--confirm', '--help'), ('--confirm', '-p'), ('--confirm=',), ('--confirm',), ('cc-shop',),
                     ('-p', 'cc-shop'), ('--confirm', 'cc-shop', 'extra')):
            with self.subTest(args=args):
                self.commands.unlink(missing_ok=True)
                result = self.cli(*args)
                self.assertEqual((result.returncode, result.stdout, result.stderr), (2, '', usage))
                self.assertEqual(self.calls(), [])
        for text in ('services:\n  db:\n    image: postgres:17\n', "name: ''\nservices: {}\n", 'name: ~\n',
                     'x-meta:\n  name: cc-shop\n'):
            with self.subTest(text=text):
                (self.root / 'dev/compose.yml').write_text(text)
                result = self.cli('--confirm', 'cc-shop')
                self.assertEqual((result.returncode, result.stdout, result.stderr), (2, '', (
                    f'ERROR: {self.root / "dev/compose.yml"} has no top-level name: add one (oasis doctor checks it), '
                    'then run recreate-postgres-volume again.\n')))
                self.assertEqual(self.calls(), [])

    def test_usage_errors_and_a_compose_file_without_a_name(self):
        # Like drop-database, the usage names the entry point that ran the tool.
        usage = f'Usage: {ROOT / "oasis"} [--confirm <compose project>]\n'
        for args in (('--confirm',), ('--confirm=',), ('--conf', 'cc-shop'), ('extra',),
                     ('--confirm', 'a', '--confirm', 'a')):
            with self.subTest(args=args):
                result = self.cli(*args)
                self.assertEqual((result.returncode, result.stdout, result.stderr), (2, '', usage))
        result = self.cli('--help')
        self.assertEqual((result.returncode, result.stderr), (0, ''))
        self.assertTrue(result.stdout.startswith(usage), result.stdout)
        (self.root / 'dev/compose.yml').write_text('services:\n  db:\n    image: postgres:17\n')
        result = self.cli('--confirm', 'cc-shop')
        self.assertEqual((result.returncode, result.stdout, result.stderr), (2, '', (
            f'ERROR: {self.root / "dev/compose.yml"} has no top-level name: add one (oasis doctor checks it), then run '
            'recreate-postgres-volume again.\n')))
        self.assertEqual(self.calls(), [])


class RecreateVolumeAliasTests(unittest.TestCase):
    """v0.20.0 S13: recreate-database-volume, the deprecated alias of recreate-postgres-volume, runs it exactly (Tier B,
    --confirm <compose project>), with one deprecation line first on stderr."""
    DEPRECATION = ('WARNING: recreate-database-volume is a deprecated alias of recreate-postgres-volume: run '
                   'recreate-postgres-volume instead.\n')
    setUp_fixture = lifecycle.LifecycleTests.setUp
    setUp = RecreateVolumeTests.setUp
    cli = RecreateVolumeTests.cli
    calls = RecreateVolumeTests.calls

    def test_the_alias_runs_the_same_and_prints_the_deprecation_line(self):
        for args in ((), ('--confirm', 'other'), ('--confirm', 'cc-shop'), ('--help',), ('extra',)):
            with self.subTest(args=args):
                self.commands.unlink(missing_ok=True)
                new = self.cli(*args)
                new_calls = self.calls()
                self.commands.unlink(missing_ok=True)
                old = self.cli(*args, command='recreate-database-volume')
                self.assertEqual((old.returncode, old.stdout, old.stderr),
                                 (new.returncode, new.stdout, self.DEPRECATION + new.stderr))
                self.assertEqual(self.calls(), new_calls)
        # Without --confirm nothing changes and the command it names is the new one.
        old = self.cli(command='recreate-database-volume')
        self.assertEqual(old.returncode, 2)
        self.assertIn(shlex.join(['oasis', '--project', str(self.root), 'recreate-postgres-volume', '--confirm', 'cc-shop']),
                      old.stderr)
        self.assertNotIn('recreate-database-volume', old.stdout + old.stderr.removeprefix(self.DEPRECATION))


if __name__ == '__main__':
    unittest.main()
